const TITRE_IMG="data:image/jpeg;base64,";
function beginNew(){try{SaveIO.clear();}catch(e){}startGame(false);}

/* ================================================================
   ÉCRAN TITRE
   L'ancien écran était le récit suivi d'un unique bouton, et la
   « nouvelle partie » effaçait la sauvegarde sans confirmation. Menu en
   bonne et due forme : reprise avec résumé de la partie, création avec
   garde-fou, récit, réglages audio, commandes, crédits.
   Les écrans de mort et de victoire réutilisent .story et #startBtn : ce
   menu se contente de se masquer quand la partie démarre.
   ================================================================ */

/* ================================================================
   EXPORTER / IMPORTER UNE SAUVEGARDE                       (v8.80)

   La sauvegarde est déjà une simple chaîne de JSON écrite à un seul
   endroit : tout ce qui suit se branche dessus sans toucher au jeu.

   Deux formes, une seule source :
     · un FICHIER .json — sur PC, la boîte « Enregistrer sous » ;
     · un CODE texte — partout ailleurs, quand aucun fichier n'est
       possible (WebView Android sans sélecteur, WKWebView iOS).

   Le code est compressé maison. `CompressionStream` ferait ça en trois
   lignes mais exige iOS 16.4, très au-dessus de notre socle iOS 13.
   ================================================================ */

/* --- compression LZ maison, sans dépendance ---------------------- */
function _lzComprimer(txt){
  if(!txt)return '';
  /* On amorce avec le PREMIER caractère. Partir d'une phrase vide faisait
     émettre `''.charCodeAt(0)`, donc NaN, donc un caractère nul en tête du
     flux : la décompression rendait le texte précédé d'un octet zéro. */
  const dico={};let phrase=txt.charAt(0),out=[],code=256;
  for(let i=1;i<txt.length;i++){
    const c=txt.charAt(i), p=phrase+c;
    if(dico[p]!=null)phrase=p;
    else{ out.push(phrase.length>1?dico[phrase]:phrase.charCodeAt(0));
          dico[p]=code++; phrase=c; }
  }
  if(phrase!=='')out.push(phrase.length>1?dico[phrase]:phrase.charCodeAt(0));
  /* chaque code tient sur 16 bits : on les écrit en caractères */
  let s='';for(const n of out)s+=String.fromCharCode(n&0xFFFF);
  return s;
}
function _lzDecomprimer(comp){
  if(!comp)return '';
  const dico={};let code=256,prec=comp.charAt(0),out=prec,mot=prec;
  for(let i=1;i<comp.length;i++){
    const k=comp.charCodeAt(i);
    let entree;
    if(k<256)entree=comp.charAt(i);
    else if(dico[k]!=null)entree=dico[k];
    else entree=prec+prec.charAt(0);
    out+=entree;
    dico[code++]=prec+entree.charAt(0);
    prec=entree;
  }
  return out;
}
/* base64 sûre en URL et dans un message : on encode d'abord en UTF-8 */
function _versTexte(json){
  try{
    /* LE PIÈGE : la sauvegarde contient des caractères au-dessus de 255
       (é, à, « », ’, …). Or le dictionnaire LZ attribue ses codes à partir
       de 256 : un tel caractère se confondrait avec une entrée du
       dictionnaire, et la décompression rendrait un texte faux — le test
       l'a montré du premier coup. On ramène donc TOUT en octets d'abord. */
    const c=_lzComprimer(unescape(encodeURIComponent(json)));
    let bin='';for(let i=0;i<c.length;i++){const v=c.charCodeAt(i);
      bin+=String.fromCharCode(v&0xFF, (v>>8)&0xFF);}
    return 'OUTLAW1:'+btoa(bin).replace(/\+/g,'-').replace(/\//g,'_');
  }catch(e){ return 'OUTLAW0:'+btoa(unescape(encodeURIComponent(json))); }
}
function _depuisTexte(code){
  const t=String(code||'').trim().replace(/\s+/g,'');
  try{
    if(t.indexOf('OUTLAW1:')===0){
      const bin=atob(t.slice(8).replace(/-/g,'+').replace(/_/g,'/'));
      let c='';for(let i=0;i+1<bin.length;i+=2)
        c+=String.fromCharCode(bin.charCodeAt(i)|(bin.charCodeAt(i+1)<<8));
      return decodeURIComponent(escape(_lzDecomprimer(c)));
    }
    if(t.indexOf('OUTLAW0:')===0)return decodeURIComponent(escape(atob(t.slice(8))));
    if(t.charAt(0)==='{')return t;                 /* JSON collé tel quel */
  }catch(e){}
  return null;
}

/* --- une sauvegarde est-elle recevable ? -------------------------

   ELLE PEUT VENIR D'UN INCONNU. L'export/import est le seul chemin par lequel
   une donnée passe d'un joueur à un autre : une sauvegarde importée est donc
   une donnée NON FIABLE, au même titre qu'un fichier téléchargé.

   L'ancienne version n'exigeait que `lvl` et `equip`. Tout le reste passait,
   et quatre champs d'objet arrivaient non échappés dans du HTML : un objet
   nommé `<img src=x onerror=…>` s'exécutait dès l'ouverture de l'inventaire.
   Éprouvé le 29 août 2026 sur le fichier livré.

   L'échappement à la sortie (`echapperHtml` dans 01-hasard.js) est la couche
   qui protège vraiment. Celle-ci est la seconde : elle REFUSE ce qu'elle ne
   comprend pas, plutôt que de le réparer en silence — le joueur doit savoir
   que son fichier est douteux.

   ⚠ ELLE NE CHERCHE PAS À EMPÊCHER LA TRICHE. Un joueur peut se donner le
   niveau 60 dans sa propre sauvegarde ; c'est son fichier, et aucun contrôle
   embarqué ne l'en empêchera. Les bornes ci-dessous écartent l'ABSURDE, pas
   l'avantageux. */
const SAUVE_NOM_MAX=80;
function _chaineSaine(v,longMax){
  if(v==null)return true;                      /* absent : le jeu a un défaut */
  if(typeof v!=='string')return false;
  if(v.length>(longMax||SAUVE_NOM_MAX))return false;
  return !/[<>"]/.test(v);
}
function _nombreSain(v,min,max){
  if(v==null)return true;
  return typeof v==='number'&&isFinite(v)&&v>=min&&v<=max;
}
/* Un affixe : un TYPE en forme d'identifiant, une VALEUR numérique.  (v9.63)

   ⚠ LE CRIBLE S'ARRÊTAIT À LA SURFACE. Il ne vérifiait que
   `Array.isArray(it.affixes)` — jamais le contenu. Or `affixText` rend
   `tOu('affixe.'+a.t, a.t)` : un type inconnu ressort TEL QUEL, et
   `itemHTML` le concatène dans une chaîne qui part dans `tip.innerHTML`.
   Une sauvegarde reçue d'un tiers — le jeu sait les exporter, c'est fait
   pour être partagé — exécutait donc du script chez celui qui l'importait.
   Vérifié en navigateur sur le vrai chemin : `showTip` a déclenché un
   `<img onerror>`. Trois vecteurs de plus derrière : `charm.v`, `sock.v` et
   le nom d'une gemme en châsse.

   On n'exige PAS que le type existe dans `AFFIX` : une sauvegarde d'une
   version où l'affixe a disparu resterait lisible, et la forme identifiant
   suffit à exclure toute balise. */
function _affixeSain(a){
  if(a==null)return true;
  if(typeof a!=='object')return false;
  if(typeof a.t!=='string'||!/^[a-z][a-z0-9_]{0,23}$/.test(a.t))return false;
  return typeof a.v==='number'&&isFinite(a.v);
}
function _objetSain(it){
  if(!it||typeof it!=='object')return false;
  if(it.rarity!=null&&!RAR[it.rarity])return false;
  if(it.slot!=null&&it.slot!=='gem'&&it.slot!=='charm'&&P_SLOTS.indexOf(it.slot)<0)return false;
  if(!_chaineSaine(it.name)||!_chaineSaine(it.ico,16)||!_chaineSaine(it.setCol,16))return false;
  if(!_nombreSain(it.plus,0,50)||!_nombreSain(it.ilvl,1,999)||!_nombreSain(it.dura,0,9999))return false;
  if(it.affixes!=null){
    if(!Array.isArray(it.affixes))return false;
    for(const a of it.affixes) if(!_affixeSain(a))return false;
  }
  if(!_affixeSain(it.charm)||!_affixeSain(it.sock))return false;
  /* Les châsses portent des objets ENTIERS : mêmes règles, un cran plus bas.
     Sans cette descente, le nom d'une gemme sertie échappait au crible. */
  if(it.sockets!=null){
    if(!Array.isArray(it.sockets))return false;
    for(const g of it.sockets){
      if(g==null)continue;
      if(typeof g!=='object')return false;
      if(!_chaineSaine(g.name)||!_chaineSaine(g.ico,16))return false;
      if(!_affixeSain(g.sock))return false;
    }
  }
  return true;
}
function sauvegardeValide(txt){
  try{
    const o=JSON.parse(txt);
    if(!o||typeof o!=='object')return null;
    /* On exige le minimum vital. Un fichier quelconque ne doit JAMAIS
       écraser une partie. */
    if(o.lvl==null||o.equip==null)return null;
    if(!_nombreSain(o.lvl,1,999))return null;
    if(typeof o.equip!=='object')return null;
    /* Chaque objet porté, en sac ou au coffre est passé au crible : c'est par
       eux que le HTML est construit. */
    for(const sl in o.equip){ const it=o.equip[sl];
      if(it!=null&&!_objetSain(it))return null; }
    for(const liste of [o.inv,o.stash]){
      if(liste==null)continue;
      if(!Array.isArray(liste))return null;
      for(const it of liste) if(it!=null&&!_objetSain(it))return null;
    }
    return o;
  }catch(e){ return null; }
}
function nomFichierSauvegarde(o){
  const d=new Date(), p=n=>String(n).padStart(2,'0');
  return 'outlaw_niv'+(o&&o.lvl||1)+'_acte'+((o&&o.maxAct!=null?o.maxAct:0)+1)
    +'_'+d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'.json';
}

/* --- exporter ---------------------------------------------------- */
function peutTelecharger(){
  try{ const a=document.createElement('a'); return 'download' in a && !!window.Blob && !!URL.createObjectURL; }
  catch(e){ return false; }
}
/* Renvoie true si un vrai fichier est parti ; false s'il faut le code. */
function exporterSauvegarde(n){
  const cle=cleEmpl(n||emplActif);
  let txt=null; try{txt=localStorage.getItem(cle);}catch(e){}
  if(!txt&&(n||emplActif)===emplActif)txt=SaveIO.read();
  if(!txt){toast('Cet emplacement est vide.',2);return false;}
  const o=sauvegardeValide(txt);
  if(!peutTelecharger())return false;
  try{
    const b=new Blob([txt],{type:'application/json'});
    const u=URL.createObjectURL(b), a=document.createElement('a');
    a.href=u; a.download=nomFichierSauvegarde(o);
    document.body.appendChild(a); a.click();
    setTimeout(()=>{try{URL.revokeObjectURL(u);a.remove();}catch(e){}},400);
    return true;
  }catch(e){ return false; }
}
function codeSauvegarde(n){
  const cle=cleEmpl(n||emplActif);
  let txt=null; try{txt=localStorage.getItem(cle);}catch(e){}
  return txt?_versTexte(txt):null;
}
/* --- importer ---------------------------------------------------- */
/* Renvoie {ok:true, resume} ou {ok:false, raison}. N'écrit QUE si tout va. */
function importerDansEmplacement(txt,n){
  const json=(String(txt||'').trim().charAt(0)==='{')?String(txt).trim():_depuisTexte(txt);
  if(!json)return{ok:false,raison:'Ce n’est pas une sauvegarde du Dernier Outlaw.'};
  const o=sauvegardeValide(json);
  if(!o)return{ok:false,raison:'Fichier illisible ou incomplet — rien n’a été touché.'};
  const cible=n||emplActif;
  try{
    /* Filet : l'ancienne sauvegarde est mise de côté avant d'écrire. */
    const av=localStorage.getItem(cleEmpl(cible));
    if(av)localStorage.setItem(cleEmpl(cible)+'_secours',av);
    localStorage.setItem(cleEmpl(cible),json);
  }catch(e){ return{ok:false,raison:'Écriture impossible (stockage plein ?).'}; }
  return{ok:true,resume:resumeSauvegarde(o),data:o};
}
/* --- lire un emplacement sans le charger ------------------------- */
/* Rend la sauvegarde d'un emplacement, ou un MARQUEUR `{illisible:true}` quand
   l'emplacement contient des données qu'on ne sait pas lire. Rendre `null` dans
   ce cas — ce qu'il faisait — affichait « — libre — » sur des heures de jeu. */
function sauvegardeEmpl(n){
  let t=null;
  try{
    t=localStorage.getItem(cleEmpl(n));
    if(!t&&n===1&&window.OutlawSave&&window.OutlawSave.read)t=window.OutlawSave.read();
  }catch(e){ t=null; }
  if(!t)return null;
  const d=diagnostiquerSauvegarde(t);
  if(d.etat===SAUVE_ILLISIBLE)return {illisible:true,erreur:d.erreur,taille:d.taille};
  /* Du JSON valide mais sans niveau : ce n'est pas une partie. */
  if(!d.s||d.s.lvl==null)return {illisible:true,erreur:'partie sans niveau',taille:d.taille};
  return d.s;
}
function supprimerEmpl(n){
  try{
    const av=localStorage.getItem(cleEmpl(n));
    if(av)localStorage.setItem(cleEmpl(n)+'_secours',av);
    localStorage.removeItem(cleEmpl(n));
  }catch(e){}
  if(n===1){try{ if(window.OutlawSave&&window.OutlawSave.clear)window.OutlawSave.clear(); }catch(e){}}
}

function lireSauvegarde(){
  try{const s=JSON.parse(SaveIO.read());return (s&&s.lvl!=null)?s:null;}catch(e){return null;}
}
function resumeSauvegarde(s){
  if(!s)return '';
  if(s.illisible)
    return '<span style="color:#ff8a6a">⚠ Sauvegarde illisible</span>'
         +'<br><span style="color:#8ea0c8">'+(s.taille||0)+' octets présents, non exploitables — '
         +(s.erreur||'cause inconnue')+'.<br><b>Rien n’a été effacé.</b> Exporte le contenu brut '
         +'avant de recommencer ici.</span>';
  const dn=['Normal','Cauchemar','Enfer'][s.difficulty||0]||'Normal';
  const acte=(s.maxAct!=null?s.maxAct:0)+1;
  const nomActe=(typeof ACTS!=='undefined'&&ACTS[acte-1])?ACTS[acte-1].court||ACTS[acte-1].name:'';
  const objets=(s.inv?s.inv.length:0)+(s.stash?s.stash.length:0);
  return 'Niveau <b>'+(s.lvl||1)+'</b> · Acte <b>'+acte+'</b>'+(nomActe?' — '+nomActe:'')+
         ' · <b>'+(s.kills||0).toLocaleString('fr-FR')+'</b> démons purgés'+
         '<br><b>'+(s.gold||0).toLocaleString('fr-FR')+'</b> or · <b>'+objets+'</b> objets rangés · difficulté <b>'+dn+'</b>'+
         (s.corpse?'<br><span style="color:#ffb45e">💀 un sac t\'attend encore sur le terrain</span>':'');
}
const OV_VUES={
  histoire(){
    const st=document.querySelector('#overlay .story');
    return '<h3>L\'histoire</h3>'+(st?st.innerHTML:'');
  },
  options(){
    /* Réglages disponibles AVANT la partie. On s'en tient à l'audio : les
       options de contrôle dépendent de l'appareil et se règlent en jeu. */
    const defs=OPT_DEFS.filter(d=>d.cat==='Audio');
    return '<h3>Réglages</h3>'+defs.map(d=>
      '<div class="ligne"><span>'+d.nom+'</span>'+
      '<button data-opt="'+d.k+'">'+(OPT[d.k]?'ACTIVÉ':'COUPÉ')+'</button></div>').join('')+
      '<div style="font-size:11px;color:#6b789c;margin-top:6px">Les options de contrôle (joystick, ciblage, vibrations) se règlent en jeu, dans l\'onglet Options.</div>'+
      /* Les Commandes ont perdu leur bouton : sept entrées ne tenaient pas sur
         un écran de téléphone. Elles vivent ici, sous les réglages. */
      OV_VUES.commandes();
  },
  commandes(){
    return '<h3 style="margin-top:18px">Commandes</h3>'+
      '<p><b>Au doigt</b> — glisse dans la moitié gauche pour le joystick, touche le décor à droite pour viser. '+
      'Le gros bouton frappe au corps à corps, les quatre pastilles autour lancent les sorts. Maintiens un sort pour viser.</p>'+
      '<p><b>Au clavier</b> — clic pour marcher et frapper, <b>1-4</b> pour les sorts, <b>Espace</b> potion, <b>A</b> mana, '+
      '<b>R</b> portail, <b>I</b> sac, <b>C</b> perso, <b>S</b> sorts, <b>M</b> carte, <b>J</b> quêtes, <b>O</b> options, <b>P</b> pause.</p>'+
      '<p><b>À savoir</b> — le gardien de chaque acte bloque la porte de sortie. Les grottes 🕳️ cachent des gardiens et du butin. '+
      'À la mort, ton sac et la moitié de ton or restent sur place : une tête de mort les signale sur la carte.</p>';
  },
  emplacements(){ return vueEmplacements(); },
  credits(){
    return '<h3>Crédits</h3>'+
      '<p><b>Le Dernier Outlaw</b> — action-RPG isométrique, un seul fichier, sans serveur ni dépendance.</p>'+
      '<p>Conception, code, équilibrage et intégration : Mirja.<br>'+
      'Musique et effets sonores : synthèse Web Audio écrite pour le jeu, quatre ambiances (village, exploration, combat, boss).<br>'+
      'Rendu isométrique maison, cartes générées à chaque partie.</p>'+
      '<p style="color:#6b789c">Build '+BUILD+'</p>';
  }
};
let ovVueCourante=null;
function ovMontrer(nom){
  const v=document.getElementById('ovVue');if(!v)return;
  /* Quitter la vue des emplacements oublie l'intention : sans ça, une
     bannière « Où veux-tu commencer ? » réapparaîtrait plus tard. */
  if(nom!=='emplacements')set_EmplIntention(null);
  if(ovVueCourante===nom){ovFermerVue();return;}
  ovVueCourante=nom;
  v.innerHTML='<div id="ovVueBoite"><button id="ovVueFermer" type="button" title="Fermer">✕</button>'
             +(OV_VUES[nom]?OV_VUES[nom]():'')+'</div>';
  v.className='ouvert';
  v.scrollTop=0;
  {const _f=document.getElementById('ovVueFermer'); if(_f)_f.onclick=ovFermerVue;}
  /* Toucher le fond, à côté de la boîte, referme aussi. */
  v.onclick=function(e){ if(e.target===v)ovFermerVue(); };
  /* Les bascules de réglage vivent dans la vue : on les rebranche à chaque rendu. */
  v.querySelectorAll&&Array.prototype.forEach.call(v.querySelectorAll('[data-opt]'),function(b){
    b.onclick=function(){const k=b.getAttribute('data-opt');
      optSet(k,!OPT[k]);b.textContent=OPT[k]?'ACTIVÉ':'COUPÉ';};});
  if(nom==='emplacements'&&typeof brancherEmplacements==='function')brancherEmplacements();
  ovMenuBoutons();
}
/* Un seul point de passage pour refermer la vue du titre — même raison que
   closeAllPanels et fermerCarte : trois chemins, trois oublis. */
function ovFermerVue(){
  const v=document.getElementById('ovVue');
  ovVueCourante=null;set_EmplIntention(null);
  if(v){v.innerHTML='';v.className='';v.onclick=null;}
  ovMenuBoutons();
}

/* Points de mutation exposés : ces variables sont écrites depuis d'autres
   modules, ce qu'une portée globale unique autorisait en silence. */
function setOvVueCourante(v){ovVueCourante=v;}

